SELECT (SELECT count(*) FROM t4) AS table_rows,(SELECT sum(rowid) FROM t4) AS remaining_rowid_sum,(SELECT sum(i) FROM t4) AS remaining_value_sum,(SELECT sum((rowid%2)=0 AND i=rowid AND t=printf('number %d',rowid)) FROM t4) AS correct_remaining,count(*) AS log_rows,sum(op='INSERT INTO t4') AS insert_logs,sum(op='UPDATE OF t4') AS update_logs,sum(op='DELETE OF t4') AS delete_logs,sum(CASE WHEN op='DELETE OF t4' THEN r ELSE 0 END) AS deleted_rowid_sum,sum(CASE WHEN op='DELETE OF t4' THEN i ELSE 0 END) AS deleted_value_sum,sum(length(t)) AS logged_text_length FROM log;